import numpy as np
from scipy.optimize import minimize, linprog
import os

def slsqp_objective(x): return -np.sum(x[64:])

def slsqp_constraints(x):
    n = 32
    centers = x[:64].reshape((n, 2))
    radii = x[64:]
    b_con = np.concatenate([centers[:,0]-radii, 1-centers[:,0]-radii, centers[:,1]-radii, 1-centers[:,1]-radii])
    diff = centers[:, np.newaxis, :] - centers[np.newaxis, :, :]
    dist_sq = np.sum(diff**2, axis=-1)
    indices = np.triu_indices(n, k=1)
    rad_sum_sq = (radii[indices[0]] + radii[indices[1]])**2
    o_con = dist_sq[indices] - rad_sum_sq
    return np.concatenate([b_con, o_con])

def solve_exact_radii_lp(centers):
    n = 32
    c = -np.ones(n)
    A_ub, b_ub = [], []
    for i in range(n):
        x_i, y_i = centers[i]
        r1=np.zeros(n); r1[i]=1; A_ub.append(r1); b_ub.append(x_i)
        r2=np.zeros(n); r2[i]=1; A_ub.append(r2); b_ub.append(1-x_i)
        r3=np.zeros(n); r3[i]=1; A_ub.append(r3); b_ub.append(y_i)
        r4=np.zeros(n); r4[i]=1; A_ub.append(r4); b_ub.append(1-y_i)
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.linalg.norm(centers[i] - centers[j])
            row = np.zeros(n); row[i] = 1; row[j] = 1
            A_ub.append(row); b_ub.append(dist)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub), bounds=bounds, method='highs')
    return result.x if result.success else np.full(n, 0.01)

def finalize_radii(centers, radii):
    n = 32; final_radii = np.copy(radii); epsilon = 1e-9
    for i in range(n):
        x_i, y_i = centers[i]
        final_radii[i] = min(final_radii[i], x_i, 1 - x_i, y_i, 1 - y_i)
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.linalg.norm(centers[i] - centers[j])
            rad_sum = final_radii[i] + final_radii[j]
            if rad_sum > dist:
                reduction = (rad_sum - dist) / 2.0 + epsilon
                final_radii[i] -= reduction; final_radii[j] -= reduction
    return np.maximum(final_radii, 0)

def construct_packing() -> tuple:
    n = 32
    num_starts = 8
    best_slsqp_score = -np.inf
    best_slsqp_solution = None
    rng = np.random.default_rng(42)

    # --- STAGE 1: Find best centers with SLSQP ---
    for i in range(num_starts):
        if i % 2 == 0:
            centers_0 = [];
            for r in range(6):
                for c in range(6):
                    if len(centers_0)<n: centers_0.append([0.1+c*0.16, 0.1+r*0.16])
            centers_0 = np.array(centers_0) + rng.uniform(-0.04, 0.04, (n,2))
        else:
            centers_0 = np.zeros((n,2)); centers_0[0] = rng.random(2)
            for j in range(1, n):
                best_c=None; max_min_d=-1
                for _ in range(100):
                    c=rng.random(2); min_d=np.min(np.linalg.norm(centers_0[:j]-c,axis=1))
                    if min_d > max_min_d: max_min_d=min_d; best_c=c
                centers_0[j] = best_c

        x0 = np.concatenate([centers_0.flatten(), np.full(n, 0.05)])
        bounds = [(0, 1)]*(2*n)+[(0,0.5)]*n
        cons = [{'type': 'ineq', 'fun': slsqp_constraints}]
        result = minimize(slsqp_objective, x0, method='SLSQP', bounds=bounds, constraints=cons, options={'maxiter': 200, 'ftol': 1e-7})

        if result.success and -result.fun > best_slsqp_score:
            best_slsqp_score = -result.fun
            best_slsqp_solution = result.x

    if best_slsqp_solution is None: return np.random.rand(n, 2), np.full(n, 0.01)

    # --- STAGE 2: Use LP to find optimal radii for the best centers ---
    best_centers = best_slsqp_solution[:64].reshape((n, 2))
    lp_radii = solve_exact_radii_lp(best_centers)

    # --- STAGE 3: Finalize to ensure feasibility ---
    final_radii = finalize_radii(best_centers, lp_radii)

    # Also save the robust centers for future use
    np.save('storage/socrates/slsqp_lp_centers_final.npy', best_centers)

    return best_centers, final_radii
